<?php require_once __DIR__.'/../config.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)$error='Enter a name, valid email and password of at least 8 characters.';else{try{$s=db()->prepare("INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,'customer')");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);session_regenerate_id(true);$_SESSION['user']=['id'=>(int)db()->lastInsertId(),'name'=>$name,'email'=>$email,'role'=>'customer'];header('Location: /powervault/account/');exit;}catch(Throwable $ex){$error='That email may already be registered.';}}}$pageTitle='Create Account';require __DIR__.'/../includes/header.php';?><section class="section-pad"><div class="container auth-wrap"><form method="post" class="form-panel auth-card"><div class="eyebrow">JOIN POWERVAULT</div><h1>Create account</h1><?=$error?'<div class="alert error">'.e($error).'</div>':''?><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label class="form-label">Full Name</label><input class="form-control mb-3" name="name" required><label class="form-label">Email</label><input class="form-control mb-3" name="email" type="email" required><label class="form-label">Password (minimum 8 characters)</label><input class="form-control mb-4" name="password" type="password" minlength="8" required><button class="btn btn-neon w-100">Create Account</button><p class="muted mt-3">Already registered? <a href="/powervault/account/login.php">Log in</a></p></form></div></section><?php require __DIR__.'/../includes/footer.php';?>
